const APPROVAL_PLAN: &str = r##"{"format":"macro-agsdl-compiled-plan/2","versions":{"snapshot":"2","contract":"agsdl-0.3.0","compiler":"macro-agsdl-compiler/030","runtime":"macro-agsdl-runtime/030","registry":"registry","profile":"macro-agsdl-030-v1"},"source":{"owner":{"projectId":"p","planId":"plan","branch":"feature/test"},"revision":"1","sourceSha256":"fa6a5278c40d78d14e70913dd943253dc64541f8d44367132acea6bff555b59a"},"documentJson":"{\"contract\":\"agsdl-0.3.0\",\"id\":\"test\",\"agents\":{},\"flow\":{\"entry\":\"work\",\"steps\":{\"work\":{\"type\":\"approval\",\"next\":{\"yes\":[]}}}}}","agents":[],"entry":["work"],"scopes":[{"address":[],"parent":null,"composition":null,"entry":["work"],"outputs":[],"agents":{}}],"steps":[{"address":["work"],"scope":[],"type":"approval","declarationJson":"{\"type\":\"approval\",\"next\":{\"yes\":[]}}","agent":null,"instance":null,"delivery":null,"maxVisitsJson":null,"timeoutMsJson":null,"submissionContractJson":null}],"routes":[{"source":["work"],"kind":"normal","key":"yes","declarationJson":"[]","targets":[],"inherited":false}],"joins":[],"handlers":[{"address":["work"],"scope":[],"local":false,"flow":false,"joins":[]}],"graphlessSubmissionContracts":{}}"##;

const SCHEMA: &str = r#"
PRAGMA foreign_keys=ON;
CREATE TABLE test_owner(system_id TEXT PRIMARY KEY, epoch TEXT NOT NULL, capture_epoch TEXT NOT NULL);
CREATE TABLE test_metadata(source_sha256 TEXT NOT NULL);
CREATE TABLE engine_systems(system_id TEXT, request_id TEXT UNIQUE NOT NULL);
CREATE TABLE engine_ui_intents(request_id TEXT, delivery_id TEXT);
"#;

// A fake authority exercises the transaction; it proves no native qualification.
struct Authority {
    epoch: &'static str,
    reject_after_register: bool,
    lock_ok: bool,
    capture: Option<StartCapture030>,
    calls: std::sync::Arc<std::sync::atomic::AtomicUsize>,
    barrier: std::sync::Arc<std::sync::atomic::AtomicBool>,
}
impl Authority030 for Authority {
    fn owner<'a>(
        &'a self,
        db: &'a mut SqliteConnection,
        id: &'a FlowIdentity030,
    ) -> CheckFuture<'a> {
        Box::pin(async move {
            let row = sqlx::query("SELECT epoch,capture_epoch FROM test_owner WHERE system_id=?")
                .bind(&id.system_start_id)
                .fetch_optional(db)
                .await?
                .ok_or(StoreError030::Authority)?;
            if row.get::<String, _>("epoch") != self.epoch
                || row.get::<String, _>("capture_epoch") != id.epoch
            {
                return Err(StoreError030::Authority);
            }
            Ok(())
        })
    }
    fn effect<'a>(
        &'a self,
        _db: &'a mut SqliteConnection,
        _effect: &'a FlowEffect030,
    ) -> CheckFuture<'a> {
        Box::pin(async { Err(StoreError030::Authority) })
    }
    fn settlement<'a>(
        &'a self,
        _db: &'a mut SqliteConnection,
        _effect: &'a FlowEffect030,
        _receipt: &'a Value,
    ) -> CheckFuture<'a> {
        Box::pin(async { Err(StoreError030::Authority) })
    }
    fn owner_epoch(&self) -> &str {
        self.epoch
    }
}
impl StartAuthority030 for Authority {
    type SourceGuard = ();
    fn require_clear(&self, _request: &EngineStartRequest) -> Result<()> {
        if self.barrier.load(std::sync::atomic::Ordering::SeqCst) {
            Err(failure("UNCERTAIN", "requestId", "Start exclusion is held"))
        } else {
            Ok(())
        }
    }
    fn begin_commit(
        &self,
        _request: &EngineStartRequest,
        _identity: &FlowIdentity030,
    ) -> Result<()> {
        self.barrier
            .compare_exchange(
                false,
                true,
                std::sync::atomic::Ordering::SeqCst,
                std::sync::atomic::Ordering::SeqCst,
            )
            .map_err(|_| failure("UNCERTAIN", "requestId", "Start exclusion is held"))?;
        Ok(())
    }
    fn commit_acknowledged(&self, _request: &EngineStartRequest, _identity: &FlowIdentity030) {
        self.barrier
            .store(false, std::sync::atomic::Ordering::SeqCst);
    }
    async fn capture(&self, _request: &EngineStartRequest) -> Result<StartCapture030> {
        self.calls.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        self.capture
            .clone()
            .ok_or_else(|| failure("CORRELATION", "capture", "Unexpected capture"))
    }
    async fn lock_source(&self, _request: &EngineStartRequest) -> Result<()> {
        if self.lock_ok {
            Ok(())
        } else {
            Err(failure("CAPTURE_CHANGED", "source", "changed"))
        }
    }
    async fn bind_capture_tx(
        &self,
        db: &mut SqliteConnection,
        _request: &EngineStartRequest,
        capture: &StartCapture030,
    ) -> Result<()> {
        sqlx::query("INSERT INTO test_owner VALUES(?,?,?)")
            .bind(&capture.identity.system_start_id)
            .bind(self.epoch)
            .bind(&capture.identity.epoch)
            .execute(db)
            .await?;
        if self.reject_after_register {
            return Err(failure("AUTHORITY", "", "rejected"));
        }
        Ok(())
    }
}
fn authority() -> Authority {
    Authority {
        epoch: "owner-1",
        reject_after_register: false,
        lock_ok: true,
        capture: None,
        calls: Default::default(),
        barrier: Default::default(),
    }
}
async fn start_fixture(
    pool: &SqlitePool,
    request: &EngineStartRequest,
    capture: &StartCapture030,
    authority: &Authority,
) -> Result<StartReceipt030> {
    let wrapped = Authority {
        epoch: authority.epoch,
        reject_after_register: authority.reject_after_register,
        lock_ok: authority.lock_ok,
        capture: Some(capture.clone()),
        calls: authority.calls.clone(),
        barrier: authority.barrier.clone(),
    };
    Ok(start(pool, request, &wrapped).await?.receipt)
}
async fn pool() -> SqlitePool {
    let pool = sqlx::sqlite::SqlitePoolOptions::new()
        .max_connections(1)
        .connect("sqlite::memory:")
        .await
        .unwrap();
    sqlx::raw_sql(SCHEMA).execute(&pool).await.unwrap();
    sqlx::raw_sql(include_str!("../migrations/030_execution_flow.sql"))
        .execute(&pool)
        .await
        .unwrap();
    pool
}
fn fixture(kind: &str) -> (EngineStartRequest, StartCapture030) {
    let plan_json = if kind == "call" {
        CALL_PLAN
    } else {
        APPROVAL_PLAN
    };
    let plan: Value = serde_json::from_str(plan_json).unwrap();
    let authored = plan["documentJson"].as_str().unwrap().to_owned();
    let source: EngineSourceRevision = serde_json::from_value(plan["source"].clone()).unwrap();
    let versions: EngineVersions = serde_json::from_value(plan["versions"].clone()).unwrap();
    let request: EngineStartRequest = serde_json::from_value(json!({"source":source,"profile":"macro-agsdl-030-v1","associations":{},"requestId":"request","entry":{"deliveryId":"delivery","messageJson":"{}"}})).unwrap();
    let capture = StartCapture030 {
        identity: FlowIdentity030 {
            system_start_id: "system".into(),
            flow_invocation_id: "flow".into(),
            snapshot_id: "snapshot".into(),
            epoch: "capture-epoch".into(),
        },
        source,
        versions,
        authored_source: authored,
        compiled_plan_json: plan_json.into(),
        registry_json: r#"{"format":"macro-agsdl-registry/030","version":"registry"}"#.into(),
        private_capture_json: "{}".into(),
    };
    (request, capture)
}

#[test]
fn source_document_requires_identical_numeric_tokens_but_allows_json_formatting() {
    let original = r#"{"number":1,"nested":[-0.0,1e0,9007199254740993],"text":"été"}"#;
    let formatted =
        " { \"text\":\"\\u00e9té\", \"nested\": [ -0.0, 1e0, 9007199254740993 ], \"number\": 1 } ";
    assert!(document_tokens_equal(original, formatted).unwrap());
    for altered in [
        original.replace("\"number\":1", "\"number\":1.0"),
        original.replace("\"number\":1", "\"number\":1e0"),
        original.replace("-0.0", "0"),
        original.replace("9007199254740993", "9007199254740992"),
    ] {
        assert!(!document_tokens_equal(original, &altered).unwrap());
    }
    assert!(document_tokens_equal(r#"{"a":1,"a":1}"#, r#"{"a":1}"#).is_err());

    let (mut request, mut capture) = fixture("call");
    capture.authored_source =
        capture
            .authored_source
            .replacen("\"agents\":{}", "\"agents\":{},\"number\":1", 1);
    capture.source.source_sha256 =
        format!("{:x}", Sha256::digest(capture.authored_source.as_bytes()));
    request.source = capture.source.clone();
    let mut plan: Value = serde_json::from_str(&capture.compiled_plan_json).unwrap();
    plan["source"] = serde_json::to_value(&capture.source).unwrap();
    plan["documentJson"] = capture.authored_source.clone().into();
    capture.compiled_plan_json = plan.to_string();
    assert!(validate_capture(&request, &capture).is_ok());
    for token in ["1.0", "1e0"] {
        plan["documentJson"] = capture
            .authored_source
            .replace("\"number\":1", &format!("\"number\":{token}"))
            .into();
        capture.compiled_plan_json = plan.to_string();
        assert!(validate_capture(&request, &capture).is_err());
    }
}
#[tokio::test]
async fn start_call_and_approval_are_atomic_and_replay_without_io() {
    for kind in ["call", "approval"] {
        let pool = pool().await;
        let (request, capture) = fixture(kind);
        let receipt = start_fixture(&pool, &request, &capture, &authority())
            .await
            .unwrap();
        assert_eq!(receipt.enter.as_ref().unwrap().effect_ids.len(), 1);
        assert_eq!(
            start_fixture(&pool, &request, &capture, &authority())
                .await
                .unwrap(),
            receipt
        );
        let mut changed = request.clone();
        changed.entry.as_mut().unwrap().message_json = "{\"prompt\":\"different\"}".into();
        assert!(start_fixture(&pool, &changed, &capture, &authority())
            .await
            .is_err());
        let counts: (i64, i64, i64) = (
            sqlx::query_scalar("SELECT count(*) FROM engine_start030_requests")
                .fetch_one(&pool)
                .await
                .unwrap(),
            sqlx::query_scalar("SELECT count(*) FROM engine_flow030_events")
                .fetch_one(&pool)
                .await
                .unwrap(),
            sqlx::query_scalar("SELECT count(*) FROM engine_flow030_outbox WHERE status='pending'")
                .fetch_one(&pool)
                .await
                .unwrap(),
        );
        assert_eq!(counts, (1, 1, 1));
        assert!(start_fixture(
            &pool,
            &request,
            &capture,
            &Authority {
                epoch: "old-owner",
                ..authority()
            }
        )
        .await
        .is_err());
    }
}

#[tokio::test]
async fn replay_uses_retained_capture_after_source_changes_without_new_work() {
    let pool = pool().await;
    let (request, capture) = fixture("call");
    let original = Authority {
        capture: Some(capture.clone()),
        ..authority()
    };
    let first = start(&pool, &request, &original).await.unwrap();
    assert_eq!(original.calls.load(std::sync::atomic::Ordering::SeqCst), 1);
    sqlx::query("INSERT INTO test_metadata VALUES('changed-source')")
        .execute(&pool)
        .await
        .unwrap();
    let current: String = sqlx::query_scalar("SELECT source_sha256 FROM test_metadata")
        .fetch_one(&pool)
        .await
        .unwrap();
    assert_ne!(current, capture.source.source_sha256);
    // The metadata lock mock reflects that changed source; capture would fail too.
    let changed = Authority {
        epoch: "owner-1",
        lock_ok: false,
        capture: None,
        calls: original.calls.clone(),
        ..authority()
    };
    let replay = start(&pool, &request, &changed).await.unwrap();
    assert_eq!(replay.receipt, first.receipt);
    assert_eq!(replay.capture.authored_source, capture.authored_source);
    assert_eq!(changed.calls.load(std::sync::atomic::Ordering::SeqCst), 1);
    let count: i64 = sqlx::query_scalar("SELECT count(*) FROM engine_flow030_outbox")
        .fetch_one(&pool)
        .await
        .unwrap();
    assert_eq!(count, 1);
    let mut conflict = request.clone();
    conflict.entry.as_mut().unwrap().message_json = "{\"prompt\":\"changed\"}".into();
    assert!(start(&pool, &conflict, &changed).await.is_err());
    assert!(start(
        &pool,
        &request,
        &Authority {
            epoch: "old-owner",
            ..changed
        }
    )
    .await
    .is_err());
}

