#[tokio::test]
async fn uncertain_barrier_keeps_inspection_read_only_for_committed_and_rolled_back_outcomes() {
    let pool = pool().await;
    let (request, capture) = fixture("call");
    let owner = Authority {
        capture: Some(capture.clone()),
        ..authority()
    };
    let original = start(&pool, &request, &owner).await.unwrap();
    // Model an unacknowledged successful commit; inspection does not release the fence.
    owner.begin_commit(&request, &capture.identity).unwrap();
    match inspect(&pool, &request, &owner).await.unwrap() {
        StartInspection030::Committed(retained) => assert_eq!(retained.receipt, original.receipt),
        StartInspection030::AbsentUnresolved => panic!("committed record absent"),
    }
    assert!(start(&pool, &request, &owner).await.is_err());
    assert_eq!(owner.calls.load(std::sync::atomic::Ordering::SeqCst), 1);
    let count: i64 = sqlx::query_scalar("SELECT count(*) FROM engine_flow030_outbox")
        .fetch_one(&pool)
        .await
        .unwrap();
    assert_eq!(count, 1);

    let empty = self::pool().await;
    let not_committed = Authority {
        capture: Some(capture.clone()),
        ..authority()
    };
    not_committed
        .begin_commit(&request, &capture.identity)
        .unwrap();
    {
        let mut conn = empty.acquire().await.unwrap();
        let mut tx = conn.begin_with("BEGIN IMMEDIATE").await.unwrap();
        sqlx::query("INSERT INTO test_owner VALUES('system','owner-1','capture-epoch')")
            .execute(&mut *tx)
            .await
            .unwrap();
        tx.rollback().await.unwrap();
    }
    assert!(matches!(
        inspect(&empty, &request, &not_committed).await.unwrap(),
        StartInspection030::AbsentUnresolved
    ));
    assert!(start(&empty, &request, &not_committed).await.is_err());
    assert_eq!(
        not_committed
            .calls
            .load(std::sync::atomic::Ordering::SeqCst),
        0
    );
}
#[tokio::test]
async fn refusal_rolls_back_owner_capture_flow_and_effects() {
    let pool = pool().await;
    let (request, capture) = fixture("call");
    let precommit = Authority {
        reject_after_register: true,
        capture: Some(capture.clone()),
        ..authority()
    };
    assert!(start(&pool, &request, &precommit).await.is_err());
    assert!(!precommit.barrier.load(std::sync::atomic::Ordering::SeqCst));
    assert!(start_fixture(
        &pool,
        &request,
        &capture,
        &Authority {
            reject_after_register: true,
            ..authority()
        }
    )
    .await
    .is_err());
    for (table, query) in [
        ("test_owner", "SELECT count(*) FROM test_owner"),
        (
            "engine_start030_requests",
            "SELECT count(*) FROM engine_start030_requests",
        ),
        (
            "engine_flow030_runs",
            "SELECT count(*) FROM engine_flow030_runs",
        ),
        (
            "engine_flow030_events",
            "SELECT count(*) FROM engine_flow030_events",
        ),
        (
            "engine_flow030_outbox",
            "SELECT count(*) FROM engine_flow030_outbox",
        ),
    ] {
        let count: i64 = sqlx::query_scalar(query).fetch_one(&pool).await.unwrap();
        assert_eq!(count, 0, "{table}");
    }
    assert!(start_fixture(
        &pool,
        &request,
        &capture,
        &Authority {
            lock_ok: false,
            ..authority()
        }
    )
    .await
    .is_err());
    let mut bad_plan = capture.clone();
    let mut plan: Value = serde_json::from_str(&bad_plan.compiled_plan_json).unwrap();
    plan["steps"][0]["type"] = "join".into();
    bad_plan.compiled_plan_json = plan.to_string();
    assert!(start_fixture(&pool, &request, &bad_plan, &authority())
        .await
        .is_err());
    for (table, query) in [
        ("test_owner", "SELECT count(*) FROM test_owner"),
        (
            "engine_flow030_runs",
            "SELECT count(*) FROM engine_flow030_runs",
        ),
        (
            "engine_flow030_events",
            "SELECT count(*) FROM engine_flow030_events",
        ),
        (
            "engine_flow030_outbox",
            "SELECT count(*) FROM engine_flow030_outbox",
        ),
    ] {
        let count: i64 = sqlx::query_scalar(query).fetch_one(&pool).await.unwrap();
        assert_eq!(count, 0, "{table}");
    }
}

#[tokio::test]
async fn graphless_start_does_not_invent_an_enter() {
    let pool = pool().await;
    let (mut request, mut capture) = fixture("call");
    let authored = r#"{"contract":"agsdl-0.3.0","id":"test","agents":{}}"#;
    capture.source.source_sha256 = format!("{:x}", Sha256::digest(authored.as_bytes()));
    capture.authored_source = authored.into();
    request.source = capture.source.clone();
    request.entry = None;
    let mut plan: Value = serde_json::from_str(CALL_PLAN).unwrap();
    plan["source"] = serde_json::to_value(&capture.source).unwrap();
    plan["documentJson"] = authored.into();
    plan["entry"] = Value::Null;
    for field in ["scopes", "steps", "routes", "joins", "handlers"] {
        plan[field] = json!([]);
    }
    capture.compiled_plan_json = plan.to_string();
    let receipt = start_fixture(&pool, &request, &capture, &authority())
        .await
        .unwrap();
    assert!(receipt.enter.is_none());
    let count: i64 = sqlx::query_scalar("SELECT count(*) FROM engine_flow030_events")
        .fetch_one(&pool)
        .await
        .unwrap();
    assert_eq!(count, 0);
}
